import{D as e,_ as t,f as n,g as r,k as i,o as a,p as o,v as s,x as c}from"#entry";import{t as l}from"./PKFf_0as.js";var u={class:`site-container max-w-[800px]! pt-14 sm:pt-20 prose-custom`},d=[`href`],f={__name:`privacy-policy`,setup(f){l({title:`Privacy Policy | PDFEasy`,description:`Read how PDFEasy processes PDF files in your browser and what data website hosting or future advertising may collect.`,path:`/privacy-policy`});let p=a(),m=n(()=>String(p.public.contactEmail||`kakveyket408@gmail.com`).trim());return(n,a)=>(c(),r(`main`,u,[a[2]||=t(`<p class="text-brand! font-extrabold text-sm uppercase tracking-[.18em]">Privacy information</p><h1 class="text-4xl sm:text-5xl font-extrabold tracking-tight">Privacy Policy</h1><p><strong>Last updated:</strong> October 24, 2026</p><p>This policy describes how this version of PDFEasy handles information. The website operator should review it against actual hosting, advertising, analytics, and legal requirements before publishing.</p><h2>PDF file processing</h2><p>PDF files selected in Merge PDF, Split PDF, Rotate PDF, and Organize PDF are processed locally in your browser using the pdf-lib JavaScript library. JPG and PNG pictures selected in JPG to PDF are also processed locally. These tools do not intentionally upload your chosen PDFs or pictures to a PDF conversion server, and they do not intentionally store document contents in browser storage. Downloads are generated from in-memory data and temporary browser object URLs that are released when you remove files or leave the page.</p><h2>Website requests and technical data</h2><p>Your browser requests website pages and scripts from the website host. Like many hosting systems, web servers and infrastructure providers may maintain access logs containing IP addresses, request times, user-agent information, and requested URLs for security and reliability. The actual retention period depends on the hosting configuration selected by the website owner.</p><h2>Cookies, analytics and advertisements</h2><p>The project does not load analytics or advertising scripts by default. If the operator configures a Google AdSense publisher ID, a meta tag can be added to verify site ownership without showing ads. Advertising is activated only through a separate, explicit production setting.</p><p>If Google advertising is enabled, Google and other third-party vendors may use cookies or similar identifiers to display and measure advertisements. Google&#39;s advertising cookies can support ads based on your visits to this site or other sites. You can manage Google ad personalization at <a href="https://myadcenter.google.com/" rel="noopener noreferrer" target="_blank">My Ad Center</a>; some third-party vendors also provide opt-out methods. The operator must disclose all active advertising and analytics vendors and implement any legally required consent choices before switching advertisements on.</p><p>Privacy laws and requirements vary by region. This project does not ship with a consent-management platform; the operator must configure one where required before allowing advertising scripts to run.</p><h2>Fonts</h2><p>This design requests the Inter font stylesheet and font files from Google Fonts when pages load. As with other third-party web resources, your browser connects to Google to retrieve these assets. This does not upload PDF document contents.</p><h2>Website logo</h2><p>The PDFEasy logo is delivered from Cloudinary, an image-hosting service. When your browser requests the logo, it connects to Cloudinary and may transmit standard request information, such as your IP address. This does not send your chosen PDF files or photographs to Cloudinary.</p><h2>Third-party services</h2><p>The public website may be served by a hosting company. The build relies on open-source code; it does not make API requests to an external PDF conversion service when you use the included PDF tools. If the website operator later adds other services, they should be disclosed here.</p><h2>Security and limitations</h2><p>Browser-local processing reduces the need to transfer documents to an external conversion server, but no web service or device can guarantee absolute security. Use trusted devices and modern browsers. Avoid processing documents that your employer or another organization does not permit you to handle in a web application.</p><h2>Questions</h2>`,21),o(`p`,null,[a[0]||=s(`For privacy questions, contact `,-1),o(`a`,{href:`mailto:${e(m)}`},i(e(m)),9,d),a[1]||=s(`.`,-1)])]))}};export{f as default};